, "name_ko": "핫스톤 발 마사지", "minutes": 90, "price": "450.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Trị liệu đầu vai cổ", "name_ko": "머리 · 어깨 · 목", "minutes": 30, "price": "200.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Trị liệu đầu vai lưng", "name_ko": "머리 · 어깨 · 등", "minutes": 45, "price": "300.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Liệu pháp thư giãn cho đôi mắt", "name_ko": "눈 피로 관리", "minutes": 20, "price": "200.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Liệu pháp thư giãn cho đôi mắt", "name_ko": "눈 피로 관리", "minutes": 30, "price": "300.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Chăm sóc tóc và da đầu", "name_ko": "헤어 · 두피 관리", "minutes": 60, "price": "150.000đ", "section": "Foot & Head", "section_ko": "스파 > 발 · 상체"}, {"name": "Chăm sóc da thiên nhiên", "name_ko": "천연 기본 피부관리", "minutes": 60, "price": "350.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Liệu pháp Oxy tươi", "name_ko": "산소 피부관리", "minutes": 60, "price": "500.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Trắng sáng tảo thiên nhiên", "name_ko": "해조 미백 관리", "minutes": 75, "price": "700.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Dưỡng ẩm Linseed chuyên sâu", "name_ko": "아마씨 집중 보습", "minutes": 75, "price": "800.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Trẻ hóa Linh Chi toàn diện", "name_ko": "영지 안티에이징 관리", "minutes": 75, "price": "900.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Collagen & Vàng 24k", "name_ko": "콜라겐 · 24K 골드 관리", "minutes": 90, "price": "950.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Thanh tẩy làn da", "name_ko": "피부 클렌징", "minutes": 45, "price": "350.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Ủ dưỡng làn da", "name_ko": "피부 영양 팩", "minutes": 45, "price": "400.000đ", "section": "Facial", "section_ko": "피부관리"}, {"name": "Ngâm bồn lá dao đỏ", "name_ko": "다오족 약초 입욕", "minutes": 60, "price": "150.000đ", "section": "Bath", "section_ko": "사우나 · 입욕"}], "features": ["떤선녓 공항 근처", "2인 개인실 (예약제)", "건식 · 습식 사우나 · 냉온탕", "여성 · 남성 메뉴 따로 (가격 같음)"], "deals": [], "about": {"facts": ["떤선녓 공항 가까운 마사지 · 스파", "개인실 · 공용 공간 · 사우나", "같은 메뉴를 여성 · 남성 공간에서 따로 운영"], "desc_ko": "떤선녓 공항에서 가까운 마사지 · 스파예요. 예약하면 2인 개인실을 쓸 수 있고, 사우나와 다오족 약초 입욕도 있어요. 비행기 타기 전이나 내린 뒤 들르기 좋아요.", "desc_en": "A massage spa close to Tan Son Nhat Airport. Private rooms for two are available by booking, plus saunas and a Red Dao herbal bath — handy before or after a flight.", "desc_vi": "Spa massage gần sân bay Tân Sơn Nhất. Có phòng đôi riêng khi đặt trước, xông hơi và ngâm lá thuốc người Dao đỏ — tiện ghé trước hoặc sau chuyến bay.", "reco_ko": "공항 가기 전후로 쉬어 가고 싶은 분", "reco_en": "Travelers resting before or after a flight", "reco_vi": "Khách muốn nghỉ ngơi trước hoặc sau chuyến bay"}, "note": "홈페이지에 여성 · 남성 메뉴가 같은 가격으로 따로 있어 한 번만 넣었어요 · 사우나 가격은 홈페이지에 없어요", "src": ["https://www.ngospa.vn/"]}$j$::jsonb, crawled_at = now() where shop_id = 'ngo-massage-spa' and coalesce(review, '') <> 'done';

