update public.shop_sources set crawled = coalesce(crawled, '{}'::jsonb) || $j${"address": "City International Hospital (호치민) · Bắc Hà International Hospital (하노이)", "phone": "+84 914 045 843", "about": {"facts": ["성형 · 재건외과 경력 10년 이상", "성형외과 1급 전문의 · 의사 면허 003690/HNO-GPHN", "호치민 · 하노이 국제병원에서 수술"], "desc_ko": "응우옌꽝뚜언 원장은 성형 · 재건외과 전문의예요. 호치민과 하노이의 국제병원에서 얼굴 · 코 · 가슴 · 지방흡입 수술을 해요.", "desc_en": "Dr. Nguyen Quang Tuan is a plastic and reconstructive surgeon who operates at international hospitals in Ho Chi Minh City and Hanoi — face, nose, breast and body contouring.", "desc_vi": "BS Nguyễn Quang Tuấn là bác sĩ phẫu thuật tạo hình – thẩm mỹ, phẫu thuật tại các bệnh viện quốc tế ở TP.HCM và Hà Nội.", "reco_ko": "국제병원에서 수술받고 싶은 분", "reco_en": "Those who prefer surgery in an international hospital", "reco_vi": "Người muốn phẫu thuật tại bệnh viện quốc tế"}, "note": "개인 의사 사이트예요 · 가격 · 영업시간은 없어요", "src": ["https://thammyquangtuan.com/"]}$j$::jsonb, crawled_at = now() where shop_id = 'dr-quang-tuan' and coalesce(review, '') <> 'done';

